// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

class BlankNodeOrderArrayTieTest {
	@Test
	void parsedArrayQueryKeepsExactRowsAndDeterministicConstantOrderTies() throws Exception {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?row WHERE { VALUES ?row { 2 1 } } ORDER BY (0)", null);
		assertInstanceOf(QueryRoot.class, parsed.getTupleExpr());

		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<Integer> rows = new ArrayList<>();
		try (var result = strategy.evaluate(parsed.getTupleExpr(), EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				rows.add(((Literal) row.getValue("row")).intValue());
			}
		}

		assertEquals(List.of(1, 2), rows,
				"a constant ORDER key ties every row, so the query context's total binding order must decide the result");
	}
}
